var LIBRARY_VIEW_TYPE = "jarvis-reader-library";
var LibraryView = class extends import_obsidian14.ItemView {
  plugin;
  root = null;
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
  }
  getViewType() {
    return LIBRARY_VIEW_TYPE;
  }
  getDisplayText() {
    return "\u56FE\u4E66\u5E93";
  }
  getIcon() {
    return "library-big";
  }
  async onOpen() {
    const container = this.contentEl;
    container.empty();
    container.addClass("jarvis-reader-library-view");
    this.root = ReactDOM.createRoot(container);
    this.root.render(React8.createElement(LibraryApp, { plugin: this.plugin }));
  }
  async onClose() {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
    this.contentEl.empty();
  }
};

